// https://manta-pacific.calderaexplorer.xyz/address/0x918139f96018Dcdb82A1F5C1e8d10B11Ed9396A0
pragma solidity ^0.8.20;

interface IERC20Minimal {
  function balanceOf(address account) external view returns (uint256);
  function transfer(address recipient, uint256 amount) external returns (bool);
  function allowance(address owner, address spender) external view returns (uint256);
  function approve(address spender, uint256 amount) external returns (bool);
  function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract Distribute {
  IERC20Minimal private _manta = IERC20Minimal(address(0x95CeF13441Be50d20cA4558CC0a27B601aC544E5));

  function distrubute(address[] calldata addrs, uint256[] calldata amounts) external {
    require(addrs.length == amounts.length, "Invalid length");

    uint256 total = 0;
    uint256 i = 0;
    for (i = 0; i < amounts.length; i++) {
      total += amounts[i];
    }

    _manta.transferFrom(msg.sender, address(this), total);

    for (i = 0; i < addrs.length; i++) {
      _manta.transfer(addrs[i], amounts[i]);
    }
  }
}

